'use client';

import { useState } from 'react';
import { useApp } from '@/context/AppContext';
import { Printer, Download, DollarSign, TrendingUp, TrendingDown, Wallet } from 'lucide-react';

export default function PayslipView() {
  const { userRole, tutors, calculatePayroll } = useApp();
  const [selectedTutorId, setSelectedTutorId] = useState<string>('');
  const [showPrintView, setShowPrintView] = useState(false);
  const payrollData = calculatePayroll();

  const currentTutorId = userRole === 'tutor' ? 'tutor-1' : selectedTutorId;
  const currentTutor = tutors.find(t => t.id === currentTutorId);
  const payslipData = payrollData.find(p => p.tutorId === currentTutorId);

  const handlePrint = () => {
    window.print();
  };

  if (!currentTutorId || !payslipData) {
    return (
      <div className="space-y-6">
        <div className="flex items-center gap-2">
          <Wallet size={24} className="text-blue-600" />
          <h2 className="text-2xl font-bold text-gray-900">Payslip View</h2>
        </div>

        <div className="bg-white rounded-lg shadow border border-gray-200 p-6">
          <label className="block text-sm font-medium text-gray-700 mb-2">Select Tutor</label>
          <select
            value={selectedTutorId}
            onChange={(e) => setSelectedTutorId(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Select a tutor...</option>
            {tutors.map(tutor => (
              <option key={tutor.id} value={tutor.id}>{tutor.name}</option>
            ))}
          </select>
        </div>
      </div>
    );
  }

  return (
    <div className={`space-y-6 ${showPrintView ? 'print-mode' : ''}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Wallet size={24} className="text-blue-600" />
          <h2 className="text-2xl font-bold text-gray-900">Payslip View</h2>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setShowPrintView(!showPrintView)}
            className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
          >
            <Download size={20} />
            {showPrintView ? 'Exit Print View' : 'Print View'}
          </button>
          <button
            onClick={handlePrint}
            className="print-button flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Printer size={20} />
            Print
          </button>
        </div>
      </div>

      {!showPrintView && userRole === 'admin' && (
        <div className="bg-white rounded-lg shadow border border-gray-200 p-6">
          <label className="block text-sm font-medium text-gray-700 mb-2">Select Tutor</label>
          <select
            value={selectedTutorId}
            onChange={(e) => setSelectedTutorId(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Select a tutor...</option>
            {tutors.map(tutor => (
              <option key={tutor.id} value={tutor.id}>{tutor.name}</option>
            ))}
          </select>
        </div>
      )}

      <div className={`bg-white rounded-lg shadow border border-gray-200 p-6 ${showPrintView ? 'print-payslip' : ''}`}>
        {/* Header */}
        <div className="border-b border-gray-200 pb-4 mb-6">
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Gumi Schooling</h1>
          <p className="text-gray-600">Payslip Statement</p>
          <p className="text-sm text-gray-500 mt-2">Generated on: {new Date().toLocaleDateString()}</p>
        </div>

        {/* Tutor Info */}
        <div className="bg-gray-50 rounded-lg p-4 mb-6">
          <h2 className="text-lg font-semibold text-gray-900 mb-2">Tutor Information</h2>
          <div className="grid grid-cols-2 gap-4 text-sm">
            <div>
              <span className="text-gray-600">Name:</span>
              <span className="ml-2 font-medium">{payslipData.tutorName}</span>
            </div>
            <div>
              <span className="text-gray-600">ID:</span>
              <span className="ml-2 font-medium">{payslipData.tutorId}</span>
            </div>
          </div>
        </div>

        {/* Summary */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <div className="bg-green-50 border border-green-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp size={20} className="text-green-600" />
              <span className="text-sm font-medium text-green-800">Total Earnings</span>
            </div>
            <p className="text-2xl font-bold text-green-900">Rp {payslipData.totalEarnings.toLocaleString()}</p>
          </div>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp size={20} className="text-blue-600" />
              <span className="text-sm font-medium text-blue-800">Total Bonuses</span>
            </div>
            <p className="text-2xl font-bold text-blue-900">Rp {payslipData.totalBonuses.toLocaleString()}</p>
          </div>
          <div className="bg-red-50 border border-red-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-2">
              <TrendingDown size={20} className="text-red-600" />
              <span className="text-sm font-medium text-red-800">Total Deductions</span>
            </div>
            <p className="text-2xl font-bold text-red-900">Rp {payslipData.totalDeductions.toLocaleString()}</p>
          </div>
        </div>

        {/* Detailed Breakdown */}
        <div className="mb-6">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">Detailed Breakdown</h2>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Description</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Rate</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Qty</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Amount</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Type</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {payslipData.details.map((detail, index) => (
                  <tr key={index}>
                    <td className="px-4 py-3 text-sm text-gray-900">{detail.description}</td>
                    <td className="px-4 py-3 text-sm text-gray-600">Rp {detail.rate.toLocaleString()}</td>
                    <td className="px-4 py-3 text-sm text-gray-600">{detail.quantity}</td>
                    <td className="px-4 py-3 text-sm font-medium text-gray-900">Rp {detail.amount.toLocaleString()}</td>
                    <td className="px-4 py-3 text-sm">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        detail.type === 'base' ? 'bg-gray-100 text-gray-800' :
                        detail.type === 'bonus' ? 'bg-green-100 text-green-800' :
                        'bg-red-100 text-red-800'
                      }`}>
                        {detail.type}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Final Take-Home Pay */}
        <div className="bg-gradient-to-r from-blue-500 to-blue-600 rounded-lg p-6 text-white">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-blue-100 text-sm">Final Take-Home Pay</p>
              <p className="text-4xl font-bold">Rp {payslipData.takeHomePay.toLocaleString()}</p>
            </div>
            <DollarSign size={64} className="text-blue-200" />
          </div>
        </div>

        {/* Footer */}
        <div className="mt-6 pt-4 border-t border-gray-200 text-center text-sm text-gray-500">
          <p>This is a computer-generated payslip. For any questions, please contact the administration.</p>
        </div>
      </div>

      <style jsx global>{`
        @media print {
          .print-mode {
            background: white !important;
          }
          .print-payslip {
            box-shadow: none !important;
            border: 1px solid #ddd !important;
          }
          body {
            background: white !important;
          }
          header, aside, button:not(.print-button) {
            display: none !important;
          }
          main {
            padding: 20px !important;
          }
        }
      `}</style>
    </div>
  );
}