'use client';

import { useState } from 'react';
import { useApp } from '@/context/AppContext';
import { Classroom, ClassType, LDRTag } from '@/types';
import { Plus, Users, Calendar, MapPin, Trash2, Edit } from 'lucide-react';

export default function ClassroomManager() {
  const { userRole, classrooms, tutors, addClassroom, updateClassroom, deleteClassroom } = useApp();
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingClassroom, setEditingClassroom] = useState<Classroom | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    classType: 'Kids-A' as ClassType,
    studentCount: 1,
    meetingPackage: 10,
    ldrTag: 'none' as LDRTag,
    tutorId: ''
  });

  const classTypes: ClassType[] = ['Kids-A', 'Kids-B', 'SPL-A', 'SPL-B', 'Test Prep-A', 'Test Prep-B', 'Group', 'Social Banjar/Panti', 'Free Trial'];
  const ldrTags: LDRTag[] = ['none', 'LDR>10km', 'LDR>15km', 'LDR>20km', 'Panti Klungkung'];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingClassroom) {
      updateClassroom(editingClassroom.id, formData);
      setEditingClassroom(null);
    } else {
      addClassroom(formData);
    }
    setShowAddForm(false);
    setFormData({
      name: '',
      classType: 'Kids-A',
      studentCount: 1,
      meetingPackage: 10,
      ldrTag: 'none',
      tutorId: ''
    });
  };

  const handleEdit = (classroom: Classroom) => {
    setEditingClassroom(classroom);
    setFormData({
      name: classroom.name,
      classType: classroom.classType,
      studentCount: classroom.studentCount,
      meetingPackage: classroom.meetingPackage,
      ldrTag: classroom.ldrTag,
      tutorId: classroom.tutorId
    });
    setShowAddForm(true);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this classroom?')) {
      deleteClassroom(id);
    }
  };

  if (userRole !== 'admin') {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-6">
        <div className="flex items-center gap-2 text-yellow-800">
          <Users size={20} />
          <p className="font-medium">Admin access required to manage classrooms</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Users size={24} className="text-blue-600" />
          <h2 className="text-2xl font-bold text-gray-900">Classroom Management</h2>
        </div>
        <button
          onClick={() => {
            setEditingClassroom(null);
            setShowAddForm(!showAddForm);
            setFormData({
              name: '',
              classType: 'Kids-A',
              studentCount: 1,
              meetingPackage: 10,
              ldrTag: 'none',
              tutorId: ''
            });
          }}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <Plus size={20} />
          {showAddForm ? 'Cancel' : 'Add Classroom'}
        </button>
      </div>

      {showAddForm && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">
            {editingClassroom ? 'Edit Classroom' : 'Add New Classroom'}
          </h3>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Classroom Name</label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Class Type</label>
                <select
                  value={formData.classType}
                  onChange={(e) => setFormData({ ...formData, classType: e.target.value as ClassType })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  {classTypes.map(type => (
                    <option key={type} value={type}>{type}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tutor</label>
                <select
                  value={formData.tutorId}
                  onChange={(e) => setFormData({ ...formData, tutorId: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                >
                  <option value="">Select Tutor</option>
                  {tutors.map(tutor => (
                    <option key={tutor.id} value={tutor.id}>{tutor.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Student Count</label>
                <input
                  type="number"
                  min="1"
                  max="10"
                  value={formData.studentCount}
                  onChange={(e) => setFormData({ ...formData, studentCount: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Meeting Package</label>
                <input
                  type="number"
                  min="1"
                  value={formData.meetingPackage}
                  onChange={(e) => setFormData({ ...formData, meetingPackage: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-1">LDR Tag</label>
                <select
                  value={formData.ldrTag}
                  onChange={(e) => setFormData({ ...formData, ldrTag: e.target.value as LDRTag })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  {ldrTags.map(tag => (
                    <option key={tag} value={tag}>{tag}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="flex gap-3">
              <button
                type="submit"
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                {editingClassroom ? 'Update Classroom' : 'Add Classroom'}
              </button>
              <button
                type="button"
                onClick={() => {
                  setShowAddForm(false);
                  setEditingClassroom(null);
                }}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {classrooms.map(classroom => {
          const tutor = tutors.find(t => t.id === classroom.tutorId);
          return (
            <div key={classroom.id} className="bg-white rounded-lg shadow border border-gray-200 p-4">
              <div className="flex items-start justify-between mb-3">
                <h3 className="font-semibold text-gray-900">{classroom.name}</h3>
                <div className="flex gap-2">
                  <button
                    onClick={() => handleEdit(classroom)}
                    className="text-blue-600 hover:text-blue-800"
                  >
                    <Edit size={16} />
                  </button>
                  <button
                    onClick={() => handleDelete(classroom.id)}
                    className="text-red-600 hover:text-red-800"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>

              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2 text-gray-600">
                  <Users size={16} />
                  <span>{classroom.classType}</span>
                </div>
                <div className="flex items-center gap-2 text-gray-600">
                  <Users size={16} />
                  <span>{classroom.studentCount} students</span>
                </div>
                <div className="flex items-center gap-2 text-gray-600">
                  <Calendar size={16} />
                  <span>{classroom.meetingPackage} meetings</span>
                </div>
                {classroom.ldrTag !== 'none' && (
                  <div className="flex items-center gap-2 text-purple-600">
                    <MapPin size={16} />
                    <span>{classroom.ldrTag}</span>
                  </div>
                )}
                <div className="flex items-center gap-2 text-gray-600">
                  <Users size={16} />
                  <span>Tutor: {tutor?.name || 'Unassigned'}</span>
                </div>
                <div className="flex items-center gap-2 text-gray-600">
                  <Calendar size={16} />
                  <span>{classroom.meetings.length} meetings completed</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}